package org.retrobridge.galaxyservices.s2;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;
public final class MediaSetupActivity extends Activity{
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(24,24,24,24);TextView status=new TextView(this);status.setText("Picture and video messages\nOne recipient, one attachment per message. Existing failed messages stay unsent until you retry them.");page.addView(status);Button enable=new Button(this);enable.setText("Use Pixel for attachments");page.addView(enable);enable.setOnClickListener(v->{try{int ignored=MmsRelay.enable(this);startService(new Intent(this,LegacyService.class).putExtra("media",true));status.setText("Ready. Existing outbox entries ignored: "+ignored);}catch(Exception e){status.setText(e.getMessage());}});Button check=new Button(this);check.setText("Check connection");page.addView(check);check.setOnClickListener(v->new Thread(()->{try{org.json.JSONObject reply=MmsRelay.request(this,"GET","00000000000000000000000000000000",null,null);String result="PASS authenticated media endpoint: "+reply.getString("state");org.retrobridge.galaxyservices.Wire.writeFile(new java.io.File(getFilesDir(),"media-check.txt"),result.getBytes("UTF-8"));runOnUiThread(()->status.setText(result));}catch(Exception e){runOnUiThread(()->status.setText("Connection unavailable"));}},"media-check").start());Button recover=new Button(this);recover.setText("Recover stuck attachment");page.addView(recover);recover.setOnClickListener(v->{try{MmsRelay.recoverBaseline(this);status.setText("Ready to retry in Messaging. Nothing sent yet.");}catch(Exception e){status.setText(e.getMessage());}});setContentView(page);}
}
